const pub = $input.first().json;
const scenarioRaw = pub['Wygenerowany scenariusz'] || pub.fields?.['Wygenerowany scenariusz'] || '';

let scenario;
try {
  scenario = typeof scenarioRaw === 'string' ? JSON.parse(scenarioRaw) : scenarioRaw;
} catch (e) {
  return [{
    json: {
      publication_id: pub.id || pub.publication_id,
      chat_id: $('When called by another workflow').first().json.chat_id,
      valid: false,
      errors: ['Wygenerowany scenariusz nie jest poprawnym JSON-em: ' + e.message],
      scenario: null,
      publikacja: pub
    }
  }];
}

const errors = [];
const warnings = [];
const trigger = $('When called by another workflow').first().json;
// R3-1: typ publikacji decyduje o zakazie "ROD"
const typPub = pub['Typ publikacji'] || pub.fields?.['Typ publikacji'] || '';
const isOfertowa = /ofertow/i.test(typPub);

// === FIX 1: Resolution → instagram-story preset ===
if (scenario.resolution === 'custom' && scenario.width === 1080 && scenario.height === 1920) {
  scenario.resolution = 'instagram-story';
  delete scenario.width;
  delete scenario.height;
}
if (!scenario.resolution) scenario.resolution = 'instagram-story';

// === FIX 2: Root structure (audio + overlay → root elements) ===
if (!Array.isArray(scenario.elements)) scenario.elements = [];

const muzykaUrl = scenario.audio?.src || trigger.muzyka_url || '';
const overlayText = isOfertowa ? '' : (scenario.overlay?.text || trigger.overlay_text || '');

// AUDIO: znajdz lub dodaj, ZAWSZE override volume:0.08, loop:-1, duration:-2
let audioEl = scenario.elements.find(e => e.type === 'audio');
if (!audioEl && muzykaUrl) {
  audioEl = {
    type: 'audio',
    src: muzykaUrl,
    'fade-in': 1.5,
    'fade-out': 2.5
  };
  scenario.elements.push(audioEl);
}
if (audioEl) {
  audioEl.loop = -1;
  audioEl.duration = -2;
  audioEl.volume = 0.04;
}

if (isOfertowa) { scenario.elements = scenario.elements.filter(e => e.type !== 'text'); }
let textEl = scenario.elements.find(e => e.type === 'text');
if (!textEl && overlayText) {
  textEl = { type: 'text', text: overlayText };
  scenario.elements.push(textEl);
}
if (textEl) {
  const oldFontFamily = textEl['font-family'] || 'Roboto';
  const oldFontSize = textEl['font-size'] || 64;
  const oldFontWeight = textEl['font-weight'] || 700;
  const oldColor = textEl.color || '#FFFFFF';
  const oldBgColor = textEl['background-color'] || 'rgba(0,0,0,0.6)';
  const oldPadding = textEl.padding || 20;

  delete textEl['font-family'];
  delete textEl['font-size'];
  delete textEl['font-weight'];
  delete textEl.color;
  delete textEl['background-color'];
  delete textEl.padding;

  textEl.style = textEl.style || '001';
  textEl.settings = textEl.settings || {};
  textEl.settings['font-family'] = oldFontFamily;
  textEl.settings['font-size'] = typeof oldFontSize === 'number' ? oldFontSize + 'px' : oldFontSize;
  textEl.settings['font-weight'] = String(oldFontWeight);
  textEl.settings.color = oldColor;
  textEl.settings['background-color'] = oldBgColor;
  textEl.settings.padding = typeof oldPadding === 'number' ? oldPadding + 'px' : oldPadding;

  if (textEl.x === 'center' || typeof textEl.x === 'string') {
    delete textEl.x;
    textEl.position = 'custom';
  }
  if (typeof textEl.y !== 'number') textEl.y = 1700;
  textEl.duration = -2;
  textEl.start = textEl.start || 0;
}

delete scenario.audio;
delete scenario.overlay;

// === FIX 3: Narracja typos ===
const narracjaFixes = [
  [/szesnascie setek/gi, 'tysiac szesc set cztery'],
  [/697 ?276 ?512/g, 'szesc dziewiec siedem, dwa siedem szesc, piec jeden dwa'],
  [/www\.client-site\.pl/gi, 'wuwuwu kropka embe myslnik dzialki kropka pe el']
];

// === FIX 4: Per scene — flux resize + subtitles ===
let subtitlesAdded = 0;
let fluxResizeFixed = 0;

(scenario.scenes || []).forEach(scene => {
  if (!Array.isArray(scene.elements)) scene.elements = [];

  // Apply narracja fixes na voice elements
  scene.elements.forEach(el => {
    if (el.type === 'voice' && el.text) {
      narracjaFixes.forEach(([rx, replacement]) => {
        el.text = el.text.replace(rx, replacement);
      });
    }
    // Flux images bez resize/position → auto-dodaj
    if (el.type === 'image' && el.model === 'flux-pro') {
      if (!el.resize) { el.resize = 'cover'; fluxResizeFixed++; }
      if (!el.position) el.position = 'center-center';
    }
  });

  // Subtitles per scena: dodaj jezeli scena ma voice element + brak subtitles
  const hasVoice = scene.elements.some(el => el.type === 'voice');
  const hasSubtitles = scene.elements.some(el => el.type === 'subtitles');
  if (hasVoice && !hasSubtitles) {
    scene.elements.push({
      type: 'subtitles',
      language: 'pl',
      settings: {
        style: 'boxed-word',
        'font-family': 'NotoSans Bold',
        'font-size': 75,
        'max-words-per-line': 4,
        'word-color': '#FFFF00',
        'line-color': '#FFFFFF',
        'box-color': '#000000',
        'outline-color': '#000000',
        'outline-width': 10,
        position: 'custom',
        x: 540,
        y: 1500
      }
    });
    subtitlesAdded++;
  }
});

// === VALIDATION 1: Root fields ===
const validResolutions = ['sd', 'hd', 'full-hd', 'squared', 'instagram-story', 'instagram-feed', 'twitter-landscape', 'twitter-portrait', 'custom'];
if (!validResolutions.includes(scenario.resolution)) errors.push('resolution invalid: ' + scenario.resolution);

const scenes = scenario.scenes || [];
if (scenes.length === 0) errors.push('Scenariusz nie ma zadnych scen');

// === VALIDATION 2: Per-scene checks ===
scenes.forEach((scene, idx) => {
  const slajd = idx + 1;
  const elements = scene.elements || [];

  const imgEl = elements.find(el => el.type === 'image' && (el.src || (el.prompt && el.model)));
  if (!imgEl) errors.push('Slajd ' + slajd + ': brak image');
  else if (imgEl.src && /FOTO|PLACEHOLDER|NAZWA_PLIKU/.test(imgEl.src)) {
    errors.push('Slajd ' + slajd + ': src placeholder');
  }

  const voiceEl = elements.find(el => el.type === 'voice');
  if (voiceEl && voiceEl.text) {
    if (voiceEl.text.length < 30) errors.push('Slajd ' + slajd + ': voice.text za krotki');
    // R3-1: zakazy WSPOLNE dla kazdej rolki (kat. Rolka / Tylko Blog — Wysokie)
    const bannedAll = [
      { rx: /idealn[ay]/i,          label: 'idealny/idealna' },
      { rx: /raj nad/i,             label: 'raj nad...' },
      { rx: /okazja zycia/i,        label: 'okazja zycia' },
      { rx: /inwestycj[aię] marzen/i, label: 'inwestycja marzen' }
    ];
    // zakazy TYLKO dla OFERTOWEJ (kat. Ofertowe — w tym ABSOLUTNY ZAKAZ "ROD")
    // Edukacyjna/Combo MUSZA moc uzyc "ROD" ("ZD to NIE system ROD") — NIE banujemy.
    const bannedOfertowa = [
      { rx: /\bROD\b/i,               label: 'ROD' },
      { rx: /działk[ai] budowlan/i,   label: 'działka budowlana' },
      { rx: /promocj[ai]/i,           label: 'promocja' },
      { rx: /unikaln[ay] szans/i,     label: 'unikalna szansa' },
      { rx: /wyjatkow[ay] okazj/i,    label: 'wyjatkowa okazja' },
      { rx: /ostatni[ae] działk/i,    label: 'ostatnie działki' }
    ];
    const banned = isOfertowa ? bannedAll.concat(bannedOfertowa) : bannedAll;
    banned.forEach(({ rx, label }) => {
      if (rx.test(voiceEl.text)) errors.push('Slajd ' + slajd + ': zakazane slowo w narracji — "' + label + '" (popraw tekst i regeneruj)');
    });
  }
});

const hasAudio = scenario.elements.some(e => e.type === 'audio');
const hasText = scenario.elements.some(e => e.type === 'text');
const finalAudio = scenario.elements.find(e => e.type === 'audio');
const finalText = scenario.elements.find(e => e.type === 'text');

return [{
  json: {
    publication_id: pub.id || pub.publication_id,
    chat_id: trigger.chat_id,
    valid: errors.length === 0,
    errors,
    warnings,
    scenario,
    scenarioJson: JSON.stringify(scenario),
    stats: {
      resolution: scenario.resolution,
      scenes: scenes.length,
      has_audio: hasAudio,
      has_overlay: hasText,
      audio_volume: finalAudio?.volume,
      audio_loop: finalAudio?.loop,
      audio_duration: finalAudio?.duration,
      text_duration: finalText?.duration,
      text_has_settings: !!finalText?.settings,
      subtitles_added: subtitlesAdded,
      flux_resize_fixed: fluxResizeFixed,
      flux_scenes: scenes.filter(s => (s.elements || []).some(e => e.model === 'flux-pro')).length,
      real_scenes: scenes.filter(s => (s.elements || []).some(e => e.type === 'image' && e.src && !e.model)).length
    }
  }
}];

