const input = $input.first().json;
const scenario = input.scenario || input;
const elementsObj = scenario.elements || {};

const audioSrc = scenario.audio?.src || elementsObj.audio?.src || '';
const overlayText = scenario.text_overlay || elementsObj.textOverlay?.content || '';
const enableSubtitles = (scenario.subtitles?.enabled ?? scenario.subtitles?.wordByWord ?? elementsObj.subtitles?.enabled) !== false;
const VOICE_ID = 'hIssydxXZ1WuDorjx6Ic';
const VOICE_MODEL = 'elevenlabs-flash-v2-5';
const LOGO_URL = 'https://dl.dropboxusercontent.com/scl/fi/muheamff4x2b5ue9abxnh/download.jpg?rlkey=cfjuz3qovtu3b3spipfljsoum&dl=1';

// Build scenes with proper json2video v2 structure
const scenes = (scenario.scenes || []).map((s, idx) => {
  const sceneElements = [];

  // Image element (z fallback dla placeholder logo)
  if (s.type === 'image' || s.src || s.prompt) {
    const isPlaceholder = s.src && typeof s.src === 'string' && s.src.includes('PLACEHOLDER');

    if (s.src && !isPlaceholder) {
      sceneElements.push({
        type: 'image',
        src: s.src,
        resize: 'cover',
        position: 'center-center'
      });
    } else if (isPlaceholder && LOGO_URL) {
      sceneElements.push({
        type: 'image',
        src: LOGO_URL,
        resize: 'contain',
        position: 'center-center'
      });
    } else if (isPlaceholder && !LOGO_URL) {
      sceneElements.push({
        type: 'image',
        model: 'flux-pro',
        prompt: 'Minimalist black background with white centered text "M&B Investment", elegant typography, vertical 9:16 format, no other elements, clean and simple',
        'aspect-ratio': 'vertical',
        resize: 'cover',
        position: 'center-center'
      });
    } else if (s.prompt) {
      sceneElements.push({
        type: 'image',
        model: s.model || 'flux-pro',
        prompt: s.prompt,
        'aspect-ratio': s['aspect-ratio'] || 'vertical',
        resize: 'cover',
        position: 'center-center'
      });
    }
  }

  // Voice element (ElevenLabs)
  if (s.narration || s.text) {
    sceneElements.push({
      type: 'voice',
      voice: VOICE_ID,
      model: VOICE_MODEL,
      text: s.narration || s.text,
      'fade-in': 0.2,
      'fade-out': 0.2
    });
  }

  // Subtitles per scene (word-by-word)
  if (enableSubtitles && (s.narration || s.text)) {
    sceneElements.push({
      type: 'subtitles',
      style: 'word-by-word',
      language: 'pl',
      'font-family': 'Montserrat',
      'font-weight': '700',
      'font-size': 75,
      'max-words-per-line': 4,
      'outline-color': '#000000',
      'outline-width': 10,
      'word-color': '#FFFF00',
      'line-color': '#FFFFFF',
      position: 'custom',
      x: 540,
      y: 1500
    });
  }

  // Text overlay per scene (POWIERZCHNIA | CENA)
  if (overlayText) {
    sceneElements.push({
      type: 'text',
      text: overlayText,
      x: 540,
      y: 120,
      'font-size': 42,
      color: '#FFFFFF',
      'background-color': 'rgba(0,0,0,0.75)'
    });
  }

  return {
    comment: s.comment || `Slajd ${idx + 1}`,
    'background-color': s['background-color'] || '#000000',
    elements: sceneElements
  };
});

// Root-level elements: background music przez caly film
const rootElements = [];
if (audioSrc) {
  rootElements.push({
    type: 'audio',
    src: audioSrc,
    duration: -2,
    volume: 0.02,
    'fade-in': 1.5,
    'fade-out': 2.5
  });
}

const finalJson = {
  resolution: 'custom',
  width: 1080,
  height: 1920,
  quality: scenario.quality || 'high',
  draft: scenario.draft || false,
  elements: rootElements,
  scenes: scenes
};

return [{
  json: {
    ...input,
    transformed_scenario: finalJson
  }
}];
